"""Cheap fake cohort generated by the minimal model itself (for pipeline smoke tests only)."""
import numpy as np
import torch

from biotwin.data.simulate import patient_names
from biotwin.models.mechanistic import MinimalModel

rng = np.random.default_rng(0)
names = np.array(patient_names())
P, T = len(names), 7 * 288
m = MinimalModel()
th = m.log_theta.detach().exp().expand(P, -1).clone()
th[:, 5] *= torch.tensor(rng.uniform(0.5, 2, P), dtype=torch.float32)  # SI varies per patient
carbs = np.zeros((P, T), np.float32)
ins = np.full((P, T), 0.5, np.float32)
for p in range(P):
    for d in range(7):
        for hh, g in [(7, 50), (12, 70), (18, 80)]:
            k = d * 288 + hh * 12 + rng.integers(-6, 6)
            carbs[p, k] = g * rng.uniform(0.7, 1.3)
            ins[p, k] += g / 10 * rng.uniform(0.7, 1.3)
s = torch.zeros(P, 7)
s[:, 6] = 140
bg = np.zeros((P, T), np.float32)
with torch.no_grad():
    for t in range(T):
        s = m.step(s, torch.tensor(ins[:, t] - 0.5) / 5, torch.tensor(carbs[:, t]) / 5, th, torch.zeros(P))
        bg[:, t] = s[:, 6].numpy()
cgm = bg + rng.normal(0, 8, bg.shape).astype(np.float32)
np.savez_compressed("data/smoke.npz", names=names, cgm=cgm, bg=bg, insulin=ins, carbs=carbs,
                    basal=np.full(P, 0.5, np.float32))
print("bg range", bg.min(), bg.max())
